package com.yeyamo_mobile.api.booking_service.infrastructure.persistence;import java.math.BigDecimal;import java.time.Instant;import java.util.*;import com.yeyamo_mobile.api.booking_service.domain.*;import jakarta.persistence.*;
@Entity@Table(name="activity_slots")public class ActivitySlotEntity{@Id private UUID id;@Column(name="activity_id",nullable=false,length=120)private String activityId;@Column(name="owner_user_id",nullable=false,length=120)private String ownerUserId;@Column(name="starts_at",nullable=false)private Instant startsAt;@Column(name="ends_at",nullable=false)private Instant endsAt;@Column(nullable=false)private int capacity;@Column(name="reserved_count",nullable=false)private int reservedCount;@Column(name="unit_price",nullable=false,precision=12,scale=2)private BigDecimal unitPrice;@Column(nullable=false,length=3)private String currency;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private SlotStatus status;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Version private long version;
 public static ActivitySlotEntity create(String activity,String owner,Instant start,Instant end,int capacity,BigDecimal price,String currency){if(activity==null||activity.isBlank()||owner==null||owner.isBlank()||start==null||end==null||!end.isAfter(start)||capacity<1||price==null||price.signum()<0||price.scale()>2||currency==null||currency.length()!=3)throw new BookingException("INVALID_SLOT","Invalid activity slot");var e=new ActivitySlotEntity();e.id=UUID.randomUUID();e.activityId=activity;e.ownerUserId=owner;e.startsAt=start;e.endsAt=end;e.capacity=capacity;e.unitPrice=price.setScale(2);e.currency=currency.toUpperCase(Locale.ROOT);e.status=SlotStatus.OPEN;e.createdAt=Instant.now();e.updatedAt=e.createdAt;return e;}
 public void reserve(int quantity){if(status!=SlotStatus.OPEN||startsAt.isBefore(Instant.now())||quantity<1||reservedCount+quantity>capacity)throw new BookingException("SLOT_UNAVAILABLE","Not enough availability");reservedCount+=quantity;updatedAt=Instant.now();}public void release(int quantity){reservedCount=Math.max(0,reservedCount-quantity);updatedAt=Instant.now();}public void close(){status=SlotStatus.CLOSED;updatedAt=Instant.now();}public int available(){return capacity-reservedCount;}
 public UUID getId(){return id;}public String getActivityId(){return activityId;}public String getOwnerUserId(){return ownerUserId;}public Instant getStartsAt(){return startsAt;}public Instant getEndsAt(){return endsAt;}public int getCapacity(){return capacity;}public int getReservedCount(){return reservedCount;}public BigDecimal getUnitPrice(){return unitPrice;}public String getCurrency(){return currency;}public SlotStatus getStatus(){return status;}
}
